// Check thresholds and generate alerts
const metrics = $input.first().json;
const alerts = [];
const now = new Date().toISOString();

// CPU thresholds
if (metrics.system?.totalCpuPercent > 80) {
  alerts.push({
    type: 'cpu_high',
    severity: 'warning',
    message: `CPU global à ${metrics.system.totalCpuPercent}%`,
    value: metrics.system.totalCpuPercent,
    threshold: 80,
    timestamp: now
  });
}

// Queue depth
if (metrics.system?.queueDepth > 100) {
  alerts.push({
    type: 'queue_depth',
    severity: metrics.system.queueDepth > 500 ? 'critical' : 'warning',
    message: `Queue depth at ${metrics.system.queueDepth}`,
    value: metrics.system.queueDepth,
    threshold: 100,
    timestamp: now
  });
}

// Service health
const services = metrics.services || {};
for (const [name, svc] of Object.entries(services)) {
  if (svc.status === 'critical' || svc.status === 'down') {
    alerts.push({
      type: 'service_down',
      severity: 'critical',
      message: `Service ${name} is ${svc.status}`,
      service: name,
      status: svc.status,
      timestamp: now
    });
  }
  if (svc.error_rate > 0.05) {
    alerts.push({
      type: 'error_rate',
      severity: 'warning',
      message: `Service ${name} error rate at ${(svc.error_rate * 100).toFixed(1)}%`,
      service: name,
      value: svc.error_rate,
      threshold: 0.05,
      timestamp: now
    });
  }
}

return alerts;

// Route alerts by severity
const alerts = $input.all();
const critical = [];
const warning = [];

for (const item of alerts) {
  const alert = item.json;
  if (alert.severity === 'critical') {
    critical.push(alert);
  } else {
    warning.push(alert);
  }
}

return { critical, warning, total: alerts.length };

// ═══ KOS BROKEN LINK AUTO-FIX ENGINE ═══
// Heuristic auto-fix engine — zero new tables, zero new edge functions
// Uses existing url_check_results and site_health_checks

const brokenLinks = $input.all()[0]?.json || [];
const knownPathsRaw = $input.all()[1]?.json || [];
const corrections = [];

// Known URL path inventory (from crawled URLs)
const PATH_INVENTORY = new Set();
for (const p of knownPathsRaw) {
  if (p.target_url) PATH_INVENTORY.add(p.target_url);
}

// Levenshtein distance for fuzzy matching
function levenshtein(a, b) {
  const m = a.length, n = b.length;
  if (m === 0) return n;
  if (n === 0) return m;
  const dp = Array.from({length: m + 1}, () => Array(n + 1).fill(0));
  for (let i = 0; i <= m; i++) dp[i][0] = i;
  for (let j = 0; j <= n; j++) dp[0][j] = j;
  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      dp[i][j] = a[i - 1] === b[j - 1]
        ? dp[i - 1][j - 1]
        : 1 + Math.min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]);
    }
  }
  return dp[m][n];
}

// Known redirects (blog slug changes, restructuring)
const KNOWN_REDIRECTS = {
  '/blog/daf-externalise-pilotage-financier-pme-afrique': '/blog/daf',
  '/blog/controle-interne-tresorerie-pme-afrique-syscohada': '/blog/controle-interne-tresorerie',
};

for (const link of brokenLinks) {
  const target = link.target_url || '';
  let corrected = null;
  let strategy = 'none';
  let confidence = 0;

  // Strategy 1: Trailing slash mismatch
  if (!corrected && target.length > 1) {
    if (target.endsWith('/')) {
      const noSlash = target.slice(0, -1);
      if (PATH_INVENTORY.has(noSlash)) {
        corrected = noSlash;
        strategy = 'trailing_slash';
        confidence = 95;
      }
    } else {
      const withSlash = target + '/';
      if (PATH_INVENTORY.has(withSlash)) {
        corrected = withSlash;
        strategy = 'trailing_slash';
        confidence = 95;
      }
    }
  }

  // Strategy 2: Fuzzy match (Levenshtein distance ≤ 3)
  if (!corrected) {
    let bestMatch = null, bestDist = 99;
    for (const known of PATH_INVENTORY) {
      const dist = levenshtein(target, known);
      if (dist < bestDist && dist <= 3) {
        bestDist = dist;
        bestMatch = known;
      }
    }
    if (bestMatch) {
      corrected = bestMatch;
      strategy = 'fuzzy_levenshtein';
      confidence = Math.max(100 - bestDist * 25, 50);
    }
  }

  // Strategy 3: Known redirects (blog slug changes)
  if (!corrected) {
    corrected = KNOWN_REDIRECTS[target] || null;
    if (corrected) {
      strategy = 'known_redirect';
      confidence = 100;
    }
  }

  corrections.push({
    target_url: target,
    source_url: link.source_url || 'unknown',
    status_code: link.status_code,
    error_message: link.error_message || '',
    corrected_url: corrected,
    fix_strategy: strategy,
    correction_confidence: confidence,
    action: corrected ? 'auto_redirect' : 'manual_review',
    timestamp: new Date().toISOString(),
  });
}

return {
  corrections,
  auto_fixable: corrections.filter(c => c.action === 'auto_redirect'),
  manual: corrections.filter(c => c.action === 'manual_review'),
  summary: {
    total_broken: corrections.length,
    auto_fixable: corrections.filter(c => c.action === 'auto_redirect').length,
    manual_review: corrections.filter(c => c.action === 'manual_review').length,
    fix_rate_pct: corrections.length > 0
      ? Math.round(corrections.filter(c => c.action === 'auto_redirect').length / corrections.length * 100)
      : 0,
  },
};
